const std = @import("std");

fn mergeSort(arr: []i32) void {
    if (arr.len <= 1) return;
    const mid = arr.len / 2;
    mergeSort(arr[0..mid]);
    mergeSort(arr[mid..arr.len]);

    var i: usize = 0;
    var j: usize = mid;
    var k: usize = 0;
    var temp: [100]i32 = undefined;

    while (i < mid and j < arr.len) {
        temp[k] = if (arr[i] < arr[j]) blk: {
            i += 1;
            break :blk arr[i - 1];
        } else blk: {
            j += 1;
            break :blk arr[j - 1];
        };
        k += 1;
    }
    while (i < mid) { temp[k] = arr[i]; i += 1; k += 1; }
    while (j < arr.len) { temp[k] = arr[j]; j += 1; k += 1; }
    for (0..k) |idx| arr[idx] = temp[idx];
}

pub fn main() !void {
    var arr = [_]i32{ 38, 27, 43, 3, 9, 82, 10 };
    mergeSort(arr);
    for (arr) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}
